BEGIN TRANSACTION;
CREATE TABLE account_snapshots (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TEXT NOT NULL,
    equity REAL,
    cash REAL,
    buying_power REAL,
    portfolio_value REAL,
    mode TEXT NOT NULL,
    source TEXT,
    raw_json TEXT
);
CREATE TABLE agent_life (
    id INTEGER PRIMARY KEY CHECK (id = 1),
    born_at TEXT NOT NULL,
    base_currency TEXT NOT NULL,
    starting_equity REAL NOT NULL,
    terminal_threshold REAL NOT NULL,
    highest_equity REAL NOT NULL,
    survival_state TEXT NOT NULL,
    terminated_at TEXT,
    terminal_reason TEXT,
    desired_running INTEGER NOT NULL DEFAULT 0,
    paper_equity REAL,
    updated_at TEXT NOT NULL
);
INSERT INTO "agent_life" VALUES(1,'2026-09-03T21:32:26.062589+00:00','GBP',100.0,40.0,100.0,'HEALTHY',NULL,NULL,1,100.0,'2026-09-04T01:21:31.344024+00:00');
CREATE TABLE ai_decisions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TEXT NOT NULL,
    symbol TEXT,
    action TEXT NOT NULL,
    confidence REAL,
    rationale TEXT,
    model TEXT,
    prompt_hash TEXT,
    raw_response TEXT,
    market_snapshot_json TEXT,
    status TEXT NOT NULL DEFAULT 'recorded'
);
CREATE TABLE contract_fills (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TEXT NOT NULL,
    fill_id TEXT NOT NULL UNIQUE,
    order_id TEXT NOT NULL,
    ticker TEXT NOT NULL,
    side TEXT NOT NULL,
    contracts INTEGER NOT NULL,
    price REAL NOT NULL,
    premium REAL NOT NULL,
    fee REAL NOT NULL,
    quote_currency TEXT NOT NULL,
    fx_rate REAL NOT NULL,
    premium_base REAL NOT NULL,
    fee_base REAL NOT NULL
);
CREATE TABLE contract_orders (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TEXT NOT NULL,
    order_id TEXT NOT NULL UNIQUE,
    idempotency_key TEXT UNIQUE,
    decision_id INTEGER,
    venue TEXT NOT NULL,
    ticker TEXT NOT NULL,
    side TEXT NOT NULL,                 -- YES | NO
    action TEXT NOT NULL,               -- BUY | SELL
    contracts INTEGER NOT NULL,
    limit_price REAL,
    status TEXT NOT NULL,
    reason TEXT,
    FOREIGN KEY (decision_id) REFERENCES decisions(id)
);
CREATE TABLE contract_positions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    position_id TEXT NOT NULL UNIQUE,
    decision_id INTEGER,
    ticker TEXT NOT NULL,
    event_key TEXT,
    side TEXT NOT NULL,
    contracts INTEGER NOT NULL,
    average_price REAL NOT NULL,
    premium_base REAL NOT NULL,
    fees_base REAL NOT NULL,
    max_loss_base REAL NOT NULL,
    max_gain_base REAL NOT NULL,
    open INTEGER NOT NULL DEFAULT 1,
    resolved_outcome INTEGER,
    settlement_base REAL,
    realised_pnl_base REAL,
    closed_at TEXT,
    FOREIGN KEY (decision_id) REFERENCES decisions(id)
);
CREATE TABLE costs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TEXT NOT NULL,
    incurred_at TEXT NOT NULL,
    category TEXT NOT NULL,             -- llm|hosting|data|fees|other
    description TEXT NOT NULL,
    amount_base REAL NOT NULL,
    currency TEXT NOT NULL,
    units REAL,
    unit_name TEXT,
    reference TEXT
);
CREATE TABLE decision_inputs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    decision_id INTEGER NOT NULL,
    name TEXT NOT NULL,
    kind TEXT NOT NULL,                 -- 'market'|'official'|'account'|'derived'|'config'
    value_json TEXT NOT NULL,
    source TEXT,
    as_of TEXT,
    FOREIGN KEY (decision_id) REFERENCES decisions(id)
);
