CREATE TABLE decisions (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TEXT NOT NULL,
    cycle_id TEXT NOT NULL,
    kind TEXT NOT NULL,                 -- 'binary' | 'spot'
    ticker TEXT,
    market_id INTEGER,
    event_key TEXT,
    opportunity_id INTEGER,

    -- what the deterministic layer computed
    model_probability REAL,
    market_probability REAL,
    gross_edge REAL,
    net_edge REAL,
    fees REAL,
    spread REAL,
    liquidity REAL,

    -- what the analyst said
    ai_model TEXT,
    ai_action TEXT,
    ai_confidence REAL,
    ai_bull TEXT,
    ai_bear TEXT,
    ai_invalidators TEXT,
    ai_raw TEXT,
    ai_validated INTEGER NOT NULL DEFAULT 0,
    ai_failure TEXT,

    -- what the guardian said
    proposed_action TEXT,
    policy_action TEXT,
    policy_reason TEXT,
    survival_state TEXT,
    risk_multiplier REAL,

    -- what risk said
    risk_approved INTEGER NOT NULL DEFAULT 0,
    risk_reason TEXT,
    risk_json TEXT,

    -- what actually happened
    final_action TEXT NOT NULL,
    executed INTEGER NOT NULL DEFAULT 0,
    order_ref TEXT,
    stage TEXT,
    equity_before REAL,
    cash_before REAL,
    base_currency TEXT,
    notes TEXT,
    FOREIGN KEY (market_id) REFERENCES markets(id),
    FOREIGN KEY (opportunity_id) REFERENCES opportunities(id)
);
